    // and the hooks lint only tolerates that behind an effect-local runner.
    const run = async () => {
      await loadProviders(() => cancelled);
    };
    void run();
    return () => {
      cancelled = true;
    };
  }, [loadProviders]);

  const refresh = useCallback(() => {
    void loadProviders();
